CREATE TABLE IF NOT EXISTS dinapay_routing_decisions(request_id UUID PRIMARY KEY,request_hash TEXT NOT NULL,response JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_entity_bindings(binding_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL CHECK(entity_type IN('merchant','account')),entity_id TEXT NOT NULL,provider TEXT NOT NULL,provider_connection_id TEXT NOT NULL,external_entity_type TEXT NOT NULL,external_entity_id TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(entity_type,entity_id,provider_connection_id,external_entity_type));
CREATE INDEX IF NOT EXISTS provider_entity_bindings_lookup_idx ON provider_entity_bindings(entity_type,entity_id,provider_connection_id,external_entity_type) WHERE active=true;
